# Asterism installer for Windows, generated by the Asterism server named below.
#
#   powershell -NoProfile -Command "Invoke-Command -ScriptBlock ([scriptblock]::Create((irm <server>/install.ps1))) -ArgumentList <agent invitation link>[,--client,claude|codex]"
#
# No execution-policy flag is needed: the policy governs script files, and this is a script block built from
# a string. That works alike from PowerShell, cmd.exe or Git Bash; or, typed in PowerShell itself:
#
#   & ([scriptblock]::Create((irm <server>/install.ps1))) <agent invitation link> [--client claude|codex]
#
# It picks the build for this processor, downloads it from the server's /dl/ (unless the same build is
# installed already), checks its SHA-256 against the server's manifest, puts it in
# ~\.asterism\bin\asterism.exe (in $env:ASTERISM_HOME\bin when that is set, as the program itself does) and
# runs `asterism join` with the arguments it was given.
# Windows PowerShell 5.1 or later. It never calls `exit`: run as a script block in the user's shell, that
# would close the shell. A failure is a terminating error instead.

$AsterismUrl = @ASTERISM_URL@
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'    # the progress bar makes downloads very slow in PowerShell 5.1

function Fail([string]$Message) { throw "asterism install: $Message" }
function Get-Sha256([string]$Path) { (Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant() }

# PowerShell 5.1 may not offer TLS 1.2 by default.
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

# The processor of the machine, not of this PowerShell process (an x64 PowerShell may run emulated on ARM64).
$arch = $null
try {
    $cpu = Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop | Select-Object -First 1
    if ($cpu.Architecture -eq 9) { $arch = 'x64' }
    elseif ($cpu.Architecture -eq 12) { $arch = 'arm64' }
} catch { }
if (-not $arch) {
    $native = $env:PROCESSOR_ARCHITEW6432
    if (-not $native) { $native = $env:PROCESSOR_ARCHITECTURE }
    if ($native -eq 'AMD64') { $arch = 'x64' }
    elseif ($native -eq 'ARM64') { $arch = 'arm64' }
}
if (-not $arch) { Fail "this processor has no build; x64 and arm64 do." }
$key = "windows-$arch"

try {
    $manifest = Invoke-RestMethod -Uri "$AsterismUrl/dl/manifest.json" -UseBasicParsing
} catch {
    Fail "could not read $AsterismUrl/dl/manifest.json ($($_.Exception.Message))."
}
$entry = $null
if ($manifest -and $manifest.files) { $entry = $manifest.files.$key }
if (-not $entry) { Fail "the server has no build for $key yet." }
$name = [string]$entry.name
$sum = ([string]$entry.sha256).ToLowerInvariant()
if ($name -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]*$') { Fail "the manifest names the build oddly ($name)." }
if ($sum -notmatch '^[0-9a-f]{64}$') { Fail "the manifest's SHA-256 for $key is not a hash." }

$stateDir = if ($env:ASTERISM_HOME) { $env:ASTERISM_HOME } else { Join-Path $HOME '.asterism' }
$binDir = Join-Path $stateDir 'bin'
$target = Join-Path $binDir 'asterism.exe'
New-Item -ItemType Directory -Force -Path $binDir | Out-Null

if ((Test-Path -LiteralPath $target -PathType Leaf) -and ((Get-Sha256 $target) -eq $sum)) {
    Write-Host "asterism install: the current build is installed already: $target"
} else {
    Write-Host "asterism install: downloading $name"
    $part = Join-Path $binDir ".asterism.part.$PID.exe"
    try {
        try {
            Invoke-WebRequest -Uri "$AsterismUrl/dl/$name" -OutFile $part -UseBasicParsing
        } catch {
            Fail "could not download $AsterismUrl/dl/$name ($($_.Exception.Message))."
        }
        $got = Get-Sha256 $part
        if ($got -ne $sum) {
            Fail "the download does not match the manifest (SHA-256 $got, expected $sum); nothing was installed."
        }
        if (Test-Path -LiteralPath $target) {
            # A running copy cannot be overwritten on Windows, but it can be renamed out of the way.
            Move-Item -LiteralPath $target -Destination (Join-Path $binDir "asterism.old.$PID.exe") -Force
        }
        Move-Item -LiteralPath $part -Destination $target
        # Old copies that are no longer running go now; one still running stays until a later install.
        Get-ChildItem -LiteralPath $binDir -Filter 'asterism.old.*.exe' -ErrorAction SilentlyContinue |
            ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue }
        Write-Host "asterism install: installed $target"
    } finally {
        Remove-Item -LiteralPath $part -Force -ErrorAction SilentlyContinue
    }
}

& $target join @args
